CKEYS = list(CITES.keys())
def cnum(key): return CKEYS.index(key) + 1
def cite(*keys):
    return "".join(f'<sup class="c"><a href="#s-{k}" title="{html.escape(CITES[k][0][:120])}">[{cnum(k)}]</a></sup>' for k in keys)
def sources_html():
    out=['<ol class="srcs">']
    for k in CKEYS:
        txt,url=CITES[k]
        out.append(f'<li id="s-{k}"><span class="snum">[{cnum(k)}]</span> {html.escape(txt)} <a class="surl" href="{url}" target="_blank" rel="noopener">↗ source</a></li>')
    out.append('</ol>'); return "".join(out)

