# ───────────────────────── the SVG showpieces (symmetric, cultural) ─────────────────────────
def chakra_svg(size=120, stroke="#1a2a6c", spokes=24):
    c=size/2; r=size*0.42; hub=size*0.07
    parts=[f'<svg viewBox="0 0 {size} {size}" width="{size}" height="{size}" xmlns="http://www.w3.org/2000/svg" aria-label="Ashoka Chakra">',
           f'<circle cx="{c}" cy="{c}" r="{r}" fill="none" stroke="{stroke}" stroke-width="{size*0.035:.1f}"/>']
    for i in range(spokes):
        a=2*math.pi*i/spokes
        x2=c+r*math.cos(a); y2=c+r*math.sin(a)
        parts.append(f'<line x1="{c:.1f}" y1="{c:.1f}" x2="{x2:.2f}" y2="{y2:.2f}" stroke="{stroke}" stroke-width="{size*0.014:.2f}"/>')
        # little spoke-pin at the rim (the Ashoka chakra's 24 spokes have rounded ends)
        parts.append(f'<circle cx="{x2:.2f}" cy="{y2:.2f}" r="{size*0.012:.2f}" fill="{stroke}"/>')
    parts.append(f'<circle cx="{c}" cy="{c}" r="{hub}" fill="{stroke}"/>')
    parts.append('</svg>')
    return "".join(parts)

def purusha_svg():
    """The Purusha — the cosmic body whose parts become the four varnas; the Dalits below, outside.
    Vertically symmetric about x=210. viewBox 0 0 420 600."""
    cx=210
    saff="#ff9933"; gold="#d4af37"; green="#2e8b3d"; red="#c0392b"; navy="#1a2a6c"; ivory="#f4e9d8"; grey="#6b6360"
    p=[f'<svg viewBox="0 0 420 600" xmlns="http://www.w3.org/2000/svg" class="purusha" role="img" aria-label="The Purusha: the four varnas born from the cosmic body, with the Dalits placed outside it">']
    # concentric mandala rings behind
    for i,rr in enumerate([250,205,160]):
        p.append(f'<circle cx="{cx}" cy="270" r="{rr}" fill="none" stroke="{gold}" stroke-opacity="{0.10+0.04*i:.2f}" stroke-width="1"/>')
    # 16 faint mandala spokes
    for i in range(16):
        a=2*math.pi*i/16; x2=cx+250*math.cos(a); y2=270+250*math.sin(a)
        p.append(f'<line x1="{cx}" y1="270" x2="{x2:.1f}" y2="{y2:.1f}" stroke="{gold}" stroke-opacity="0.05" stroke-width="1"/>')
    # ---- the body, top to bottom, each zone a varna ----
    # HEAD / MOUTH = Brahmin
    p.append(f'<circle cx="{cx}" cy="90" r="46" fill="{saff}" fill-opacity="0.22" stroke="{saff}" stroke-width="2"/>')
    p.append(f'<path d="M180 100 Q210 122 240 100" fill="none" stroke="{saff}" stroke-width="3"/>')  # the mouth
    # ARMS = Kshatriya  (symmetric)
    p.append(f'<path d="M150 175 Q90 200 78 270" fill="none" stroke="{red}" stroke-width="14" stroke-linecap="round" stroke-opacity="0.85"/>')
    p.append(f'<path d="M270 175 Q330 200 342 270" fill="none" stroke="{red}" stroke-width="14" stroke-linecap="round" stroke-opacity="0.85"/>')
    # TORSO / THIGHS = Vaishya
    p.append(f'<path d="M160 165 L260 165 L246 360 L174 360 Z" fill="{gold}" fill-opacity="0.20" stroke="{gold}" stroke-width="2"/>')
    # LEGS / FEET = Shudra (symmetric)
    p.append(f'<path d="M178 360 L204 360 L200 470 L176 470 Z" fill="{green}" fill-opacity="0.22" stroke="{green}" stroke-width="2"/>')
    p.append(f'<path d="M216 360 L242 360 L244 470 L220 470 Z" fill="{green}" fill-opacity="0.22" stroke="{green}" stroke-width="2"/>')
    p.append(f'<ellipse cx="188" cy="482" rx="22" ry="9" fill="{green}" fill-opacity="0.3" stroke="{green}" stroke-width="1.5"/>')
    p.append(f'<ellipse cx="232" cy="482" rx="22" ry="9" fill="{green}" fill-opacity="0.3" stroke="{green}" stroke-width="1.5"/>')
    # the ground line, and OUTSIDE/BELOW it = the Dalits (avarna)
    p.append(f'<line x1="40" y1="508" x2="380" y2="508" stroke="{ivory}" stroke-opacity="0.35" stroke-dasharray="5 5" stroke-width="1.5"/>')
    p.append(f'<circle cx="{cx}" cy="548" r="26" fill="none" stroke="{grey}" stroke-width="2" stroke-dasharray="4 4"/>')
    # ---- labels (symmetric, with body-part + Devanagari) ----
    def lab(x,y,anchor,dev,name,part,col):
        ax={"start":"start","middle":"middle","end":"end"}[anchor]
        return (f'<text x="{x}" y="{y}" text-anchor="{ax}" font-family="Tiro Devanagari Sanskrit,serif" font-size="17" fill="{col}">{dev}</text>'
                f'<text x="{x}" y="{y+18}" text-anchor="{ax}" font-family="Rozha One,serif" font-size="15" fill="{ivory}">{name}</text>'
                f'<text x="{x}" y="{y+34}" text-anchor="{ax}" font-family="Space Mono,monospace" font-size="9.5" fill="{col}" letter-spacing="1">{part}</text>')
    p.append(lab(cx,40,"middle","ब्राह्मण","Brahmin","THE MOUTH",saff))
    p.append(lab(372,250,"end","क्षत्रिय","Kshatriya","THE ARMS",red))
    p.append(lab(372,330,"end","वैश्य","Vaishya","THE THIGHS",gold))
    p.append(lab(372,455,"end","शूद्र","Shudra","THE FEET",green))
    p.append(lab(cx,598,"middle","दलित","Dalit · avarna","OUTSIDE THE BODY",grey))
    # left-side note
    p.append(f'<text x="48" y="250" text-anchor="start" font-family="Space Mono,monospace" font-size="9" fill="{ivory}" fill-opacity="0.55">RV 10.90</text>')
    p.append(f'<text x="48" y="264" text-anchor="start" font-family="Space Mono,monospace" font-size="9" fill="{ivory}" fill-opacity="0.55">the Purusha</text>')
    p.append('</svg>')
    return "".join(p)

